const response = $input.first().json;
const raw = response && response.choices && response.choices[0]
  && response.choices[0].message && response.choices[0].message.content;

if (!raw) {
  throw new Error('Groq returned no message content. Open the previous node to see the raw response.');
}

// JSON mode should return a bare object, but models still occasionally wrap it in a
// markdown code fence. Strip one if present before parsing.
const cleaned = String(raw).trim()
  .replace(/^```(?:json)?/i, '')
  .replace(/```$/, '')
  .trim();

let bug;
try {
  bug = JSON.parse(cleaned);
} catch (err) {
  throw new Error('Model did not return valid JSON. First 200 chars: ' + cleaned.slice(0, 200));
}

if (!bug.summary || !Array.isArray(bug.steps_to_reproduce) || bug.steps_to_reproduce.length === 0) {
  throw new Error('Report is missing summary or steps_to_reproduce. Keys returned: '
    + Object.keys(bug).join(', '));
}

const intake = $('Normalize Intake').first();

const numbered = (arr) => (arr || []).map((s, i) => (i + 1) + '. ' + s).join('\n');
const bulleted = (arr) => (arr || []).map((s) => '- ' + s).join('\n');

// Plain text, not Jira wiki markup: the Cloud API wraps a plain string in a single
// ADF paragraph, so wiki syntax would render literally.
const description = [
  'STEPS TO REPRODUCE',
  numbered(bug.steps_to_reproduce),
  '',
  'EXPECTED RESULT',
  bug.expected_result || 'Not stated.',
  '',
  'ACTUAL RESULT',
  bug.actual_result || 'Not stated.',
  '',
  'VISUAL OBSERVATIONS FROM THE SCREENSHOT',
  bulleted(bug.visual_observations) || '- None recorded.',
  '',
  'ENVIRONMENT',
  bug.environment || intake.json.environment,
  '',
  'REPORTER NOTES',
  intake.json.reporter_steps || 'None supplied.',
  '',
  'ERROR LOGS',
  intake.json.error_logs || 'None supplied.',
  '',
  '---',
  'Drafted by 08_Screenshot_To_Bug_Reporter_AIAgent from ' + intake.json.file_name + '.',
  'Model confidence: ' + (bug.confidence || 'unknown')
    + '. Suggested component: ' + (bug.suggested_component || 'unassigned') + '.',
  'Model severity: ' + (bug.severity || 'unrated')
    + '. Reporter severity: ' + intake.json.severity_hint + '.',
  'Screenshot attached. A human should confirm the steps before this is assigned.',
].join('\n');

return [{
  json: {
    summary: String(bug.summary).slice(0, 250),
    description,
    severity: bug.severity || '',
    confidence: bug.confidence || '',
    suggested_component: bug.suggested_component || '',
  },
  // The binary does not survive the HTTP hop, so pull it back for the attach step.
  binary: intake.binary,
}];

const created = $input.first().json;

if (!created.key) {
  throw new Error('Jira did not return an issue key. Response: '
    + JSON.stringify(created).slice(0, 300));
}

// Jira's create response carries no binary, so re-attach the screenshot for the
// attachment call.
return [{
  json: {
    jira_key: created.key,
    jira_id: created.id,
    summary: $('Parse Bug Report').first().json.summary,
    confidence: $('Parse Bug Report').first().json.confidence,
  },
  binary: $('Normalize Intake').first().binary,
}];
